// Eingebettet in die Vereinsverwaltung:
// dieselbe bereits angemeldete Firebase-Sitzung und dieselbe Firestore-Instanz verwenden.
// Direkter Aufruf von turnierverwaltung.html bleibt weiterhin eigenständig.
const embeddedInMain = (() => {
  try{
    return window.parent!==window
      && location.hash!=='#live-startliste'
      && !!window.parent.firebaseAuth
      && !!window.parent.firestoreDb;
  }catch(e){ return false; }
})();

const auth = embeddedInMain ? window.parent.firebaseAuth : getAuth(app);
const db = embeddedInMain ? window.parent.firestoreDb : getFirestore(app);

function onAuthStateChanged(a,cb){
  return embeddedInMain ? a.onAuthStateChanged(cb) : modOnAuthStateChanged(a,cb);
}
function signOut(a){
  return embeddedInMain ? Promise.resolve() : modSignOut(a);
}
function signInWithEmailAndPassword(a,email,pw){
  if(embeddedInMain)return Promise.reject(new Error('Bereits über Vereinsverwaltung angemeldet.'));
  return modSignInWithEmailAndPassword(a,email,pw);
}
function setPersistence(a,p){
  return embeddedInMain ? Promise.resolve() : modSetPersistence(a,p);
}

function collection(a,b){
  return embeddedInMain ? a.collection(b) : modCollection(a,b);
}
function doc(a,b,c){
  if(embeddedInMain){
    if(arguments.length===1 && a && typeof a.doc==='function')return a.doc();
    return a.collection(b).doc(c);
  }
  if(arguments.length===1)return modDoc(a);
  return modDoc(a,b,c);
}
function addDoc(ref,data){
  return embeddedInMain ? ref.add(data) : modAddDoc(ref,data);
}
function deleteDoc(ref){
  return embeddedInMain ? ref.delete() : modDeleteDoc(ref);
}
function updateDoc(ref,data){
  return embeddedInMain ? ref.update(data) : modUpdateDoc(ref,data);
}
function setDoc(ref,data,opts){
  return embeddedInMain ? ref.set(data,opts||{}) : modSetDoc(ref,data,opts);
}
function getDoc(ref){
  if(!embeddedInMain)return modGetDoc(ref);
  return ref.get().then(s=>({id:s.id,exists:()=>s.exists,data:()=>s.data()}));
}
function getDocs(ref){
  return embeddedInMain ? ref.get() : modGetDocs(ref);
}
function where(f,op,v){
  return embeddedInMain ? {__ecw:'where',f,op,v} : modWhere(f,op,v);
}
function orderBy(f,d){
  return embeddedInMain ? {__ecw:'orderBy',f,d} : modOrderBy(f,d);
}
function query(ref,...clauses){
  if(!embeddedInMain)return modQuery(ref,...clauses);
  return clauses.reduce((q,c)=>{
    if(c?.__ecw==='where')return q.where(c.f,c.op,c.v);
    if(c?.__ecw==='orderBy')return q.orderBy(c.f,c.d);
    return q;
  },ref);
}
function onSnapshot(ref,next,error){
  return embeddedInMain ? ref.onSnapshot(next,error) : modOnSnapshot(ref,next,error);
}
function serverTimestamp(){
  return embeddedInMain
    ? window.parent.firebase.firestore.FieldValue.serverTimestamp()
    : modServerTimestamp();
}
function writeBatch(a){
  return embeddedInMain ? a.batch() : modWriteBatch(a);
}

// Nur beim eigenständigen Aufruf eigene Browser-Persistenz initialisieren.
if(!embeddedInMain){
  setPersistence(auth,browserLocalPersistence).catch(e=>console.warn("Auth-Persistenz:",e));
}
let turniereUnsub = null, vereineUnsub = null, dokumenteUnsub = null, historyMeldungenUnsub = null, liveMeldungenUnsub = null, liveStartlistenViewerUnsub = null;
let vereineGeladen=false, dokumenteGeladen=false, dokumenteMeldungen=[];
let turniereCache = [], meldungenCache = [], meldungenGeladen = false, editMeldungId = null, historyMeldungenCache=[], liveMeldungenAll=[], liveStartlistenCache=[];
let liveStartlistenPublishTimer=null;
let busy = false;
let messageTimer;
function notify(message, error = false) {
  const el = document.getElementById('message');
  el.textContent = message; el.classList.remove('hidden'); el.classList.toggle('error',error);
  clearTimeout(messageTimer); messageTimer = setTimeout(() => el.classList.add('hidden'), error ? 12000 : 5000);
}
function dbError(err) {
  console.error(err);
  const code=String(err?.code||'').replace(/^firestore\//,'').replace(/^auth\//,'');
  const detail=String(err?.message||'').trim();
  const msg = code === 'permission-denied' ? 'Keine Berechtigung. Bitte die Zugriffsrechte für dein Konto prüfen.' :
    code === 'unavailable' ? 'Keine Verbindung zur Datenbank. Bitte später erneut versuchen.' :
    'Die Daten konnten nicht gespeichert oder geladen werden.'
      +(code?' Fehler: '+code+'.':'')
      +(detail?' '+detail:'');
  notify(msg,true);
}
function stopListeners() {
  [turniereUnsub,vereineUnsub,meldungenUnsub,dokumenteUnsub,historyMeldungenUnsub,liveMeldungenUnsub].forEach(fn => fn?.());
  turniereUnsub = vereineUnsub = meldungenUnsub = dokumenteUnsub = historyMeldungenUnsub = liveMeldungenUnsub = null;
  vereineGeladen=false; dokumenteGeladen=false; dokumenteMeldungen=[];
  documentDrafts.clear(); activeDocumentId="";
  turniereCache = []; vereineCache = []; meldungenCache = []; historyMeldungenCache=[]; liveMeldungenAll=[]; aktuellesTurnier = null;
  meldungenGeladen = false; editMeldungId = null;
  document.getElementById('turniereListe').replaceChildren();
  document.getElementById('dTurnierSelect').value='';
  document.getElementById('dTurnierSelect').innerHTML='<option value="">– Turnier auswählen –</option>';
  clearDocumentPreview(); updateVereineResetStatus(); resetSend();document.getElementById('mobileLinkDialog').classList.add('hidden');document.getElementById('mobileUrl').value='';document.getElementById('mobileQr').replaceChildren();document.getElementById('mobileSaveQrBtn').disabled=true;currentQrDataUrl='';currentQrFilename='';resetStartlisteEingabe();updateMobileClubSuggestions();
  document.getElementById('startlisteBody').replaceChildren();
}
function onlineStatus() {
  const el = document.getElementById('connectionStatus');
  el.classList.toggle('hidden',navigator.onLine);
  el.textContent = 'Keine Internetverbindung. Änderungen benötigen eine Verbindung zur Datenbank.';
  document.querySelectorAll('button.primary').forEach(b => b.disabled = !navigator.onLine);
  updateKapazitaetsAnzeige(); updateVereineResetStatus();
  document.getElementById("dPrintBtn").disabled=!dokumenteGeladen || imageBusy;
  updateDraftStatus();
}
window.addEventListener('offline',onlineStatus); window.addEventListener('online',onlineStatus);
window.addEventListener('unhandledrejection',e => { e.preventDefault(); dbError(e.reason || {}); });
async function saveAction(button, work) {
  if (busy) return;
  if (!navigator.onLine) { notify('Bitte zuerst eine Internetverbindung herstellen.',true); return; }
  busy = true; button.disabled = true;
  try { await work(); } catch(err) { dbError(err); }
  finally { busy = false; button.disabled = !navigator.onLine; updateKapazitaetsAnzeige(); updateVereineResetStatus(); }
}
function localToday() { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }


