    filename:specific&&aktuellesTurnier
      ?'QR_Mannschaft_anmelden_'+String(aktuellesTurnier.name||'Turnier').replace(/[^\wäöüÄÖÜß-]+/g,'_')+'.gif'
      :'QR_Mannschaft_anmelden.gif',
