// ---------- Auth ----------
const loginScreen = document.getElementById("loginScreen");
const appScreen = document.getElementById("app");

let authCheckSeq=0;
onAuthStateChanged(auth, async (user) => {
  const seq=++authCheckSeq;
  stopListeners();
  if(liveStartPublicMode){
    loginScreen.classList.add("hidden");appScreen.classList.remove("hidden");document.body.classList.add('live-start-public');startLiveStartlistenViewer();showLiveStartliste();return;
  }
  if (!user) {
    if(embeddedInMain){
      loginScreen.classList.add("hidden");
      appScreen.classList.add("hidden");
      notify("Bitte zuerst in der Vereinsverwaltung als Administrator anmelden.",true);
      return;
    }
    loginScreen.classList.remove("hidden");
    appScreen.classList.add("hidden");
    return;
  }
  try {
    const prof=await getDoc(doc(db,"users",user.uid));
    if(seq!==authCheckSeq)return;
    if(!prof.exists() || prof.data().admin!==true){
      document.getElementById("loginError").textContent="Die Turnierverwaltung ist nur für Administratoren freigegeben.";
      await signOut(auth);
      return;
    }
    loginScreen.classList.add("hidden");
    appScreen.classList.remove("hidden");
    if(embeddedInMain){
      document.body.classList.add('embedded-main-auth');
      document.getElementById("logoutBtn").style.display="none";
    }
    document.getElementById("userStatus").textContent = "Administrator: " + user.email;
    startListeners(); onlineStatus(); routeFromHash();
  } catch(err) {
    console.error(err);
    loginScreen.classList.remove("hidden");
    appScreen.classList.add("hidden");
    document.getElementById("loginError").textContent="Administrator-Berechtigung konnte nicht geprüft werden.";
  }
});

document.getElementById("loginBtn").addEventListener("click", async () => {
  const email = document.getElementById("loginEmail").value.trim();
  const pw = document.getElementById("loginPassword").value;
  const errEl = document.getElementById("loginError");
  errEl.textContent = "";
  try {
    await setPersistence(auth,browserLocalPersistence);
    await signInWithEmailAndPassword(auth, email, pw);
    document.getElementById("loginPassword").value="";
  } catch(err) {
    console.error(err);
    errEl.textContent = "Anmeldung fehlgeschlagen. Bitte E-Mail, Passwort und Internetverbindung prüfen.";
  }
});

document.getElementById("logoutBtn").addEventListener("click", () => {
  signOut(auth);
});

