function showView(viewId, navId) {
  document.body.classList.toggle('ecw-wide-view',['viewTurnierDetail','viewArchiv','viewVereine','viewHistorie'].includes(viewId));
  if(mobileMode && !['viewTurniereListe','viewTurnierDetail','viewLiveStartliste'].includes(viewId)){viewId='viewTurniereListe';navId='navTurniere';}
  ['viewAnlegen','viewTurniereListe','viewLiveStartliste','viewArchiv','viewTurnierDetail','viewVereine','viewHistorie','viewDokumente','viewSenden'].forEach(id => document.getElementById(id).classList.toggle('hidden',id !== viewId));
  ['navAnlegen','navTurniere','navLiveStartliste','navArchiv','navVereine','navHistorie','navDokumente','navSenden'].forEach(id => { const b=document.getElementById(id); b.classList.toggle('active',id===navId); b.setAttribute('aria-current',id===navId?'page':'false'); });
  if(viewId !== 'viewDokumente') { if(dokumenteUnsub) dokumenteUnsub(); dokumenteUnsub=null; clearDocumentPreview(); }
  else if(document.getElementById('dTurnierSelect').value && !dokumenteUnsub) loadDocumentMeldungen();
  if(viewId !== 'viewTurnierDetail' && meldungenUnsub) { meldungenUnsub(); meldungenUnsub=null; meldungenGeladen=false; }
}
function showTurniereListe() { showView('viewTurniereListe','navTurniere'); }
function showVereine() { showView('viewVereine','navVereine'); }
function showArchiv(){showView('viewArchiv','navArchiv');renderArchiv();}
function showHistorie(){showView('viewHistorie','navHistorie');renderHistory();}
function showTurnierDetail() { showView('viewTurnierDetail','navTurniere'); }
function routeFromHash() {
  if(location.hash==='#mobil'||location.hash.startsWith('#mobil='))mobileMode=true;
  applyMobileMode();
  if (!auth.currentUser) return;
  if(mobileMode){
    if(location.hash.startsWith('#mobil=')){const id=mobileHashId(),t=turniereCache.find(t=>t.id===id);if(t)openTurnier(id,t);else showTurniereListe();}
    else {if(location.hash!=='#mobil')history.replaceState(null,'','#mobil');showTurniereListe();}
    return;
  }
  const hash = location.hash;
  if(hash==='#live-startliste'){showLiveStartliste();return;}
  if(hash.startsWith('#turnier=')) {
    const id=decodeURIComponent(hash.slice(9)); const t=turniereCache.find(t => t.id===id);
    if(t) openTurnier(id,t); else showTurniereListe();
  } else if(hash==='#verwalten') showTurniereListe();
  else if(hash==='#archiv') showArchiv();
  else if(hash==='#vereine') showVereine();
  else if(hash==='#historie') {showHistorie();}
  else if(hash==='#senden') {showView('viewSenden','navSenden');updateSendStatus();}
  else if(hash==='#dokumente') showView('viewDokumente','navDokumente');
  else showView('viewAnlegen','navAnlegen');
}
function navigate(hash) { if(location.hash===hash) routeFromHash(); else location.hash=hash; }
window.addEventListener('hashchange',routeFromHash);
document.getElementById('navAnlegen').addEventListener('click',()=>navigate('#anlegen'));
navTurniere.addEventListener('click',()=>navigate('#verwalten'));
