// ---------- Uhrzeit-Auswahl (halbstündlich) ----------
function buildZeitOptions(selectEl, placeholder) {
  let html = `<option value="">${placeholder}</option>`;
  for (let h = 0; h < 24; h++) {
    for (let m = 0; m < 60; m += 30) {
      const hh = String(h).padStart(2, "0");
      const mm = String(m).padStart(2, "0");
      html += `<option value="${hh}:${mm}">${hh}:${mm}</option>`;
    }
  }
  selectEl.innerHTML = html;
}
buildZeitOptions(document.getElementById("tUhrzeit"), "– Uhrzeit wählen –");
buildZeitOptions(document.getElementById("tMeldeUhrzeit"), "– Uhrzeit wählen –");
buildZeitOptions(document.getElementById("tdEditUhrzeit"), "– Uhrzeit wählen –");
buildZeitOptions(document.getElementById("tdEditMeldeUhrzeit"), "– Uhrzeit wählen –");

// ---------- Mannschafts-Auswahl (maximale Anzahl) ----------
function buildMaxOptions(selectEl) {
  let html = '<option value="">– unbegrenzt –</option>';
  for (let n = 2; n <= 42; n++) {
    html += `<option value="${n}">${n}</option>`;
  }
  selectEl.innerHTML = html;
}
buildMaxOptions(document.getElementById("tMax"));
buildMaxOptions(document.getElementById("tdEditMax"));

// ---------- Daten-Caches ----------
