document.getElementById('dOriginalImagesBtn').addEventListener('click',()=>{const d=currentDraft();if(!d)return;d.values.logo='';d.values.titelbild='';d.dirty=true;renderDocumentPreview();});
async function waitForDocumentImages(){await Promise.all([...document.querySelectorAll('#printArea img')].map(img=>img.decode?.().catch(()=>{})||Promise.resolve()));await document.fonts?.ready;}
